    if (!bt_addr_le_is_bonded(BT_ID_DEFAULT, &conn->le.dst)) {
        return BT_SECURITY_ERR_SUCCESS;
    }

    BT_LOGD("le bond lost");
    return BT_SECURITY_ERR_SUCCESS;
}
