static void pair_norm_addr(const char *in, char *out, size_t out_len)
{
  size_t n = 0;

  while (*in != '\0' && n + 1u < out_len)
    {
      const char c = *in++;

      if (c == ':' || c == ' ' || c == '\t' || c == ',')
        {
          continue;
        }
      out[n++] = (c >= 'a' && c <= 'f') ? (char)(c - 'a' + 'A') : c;
    }
  out[n] = '\0';
}

