1	#!/usr/bin/env python3
2	"""板级补丁：把 zblue 的配对密钥（含 IRK/LTK）落盘到 `/mnt/kv/bt_keys.bin`。
3	
4	`CONFIG_SETTINGS` 关着 ⇒ zblue 的 `bt_keys_store()`（→ `bt_settings_store_keys()`）是空动作，
5	配对出来的 LTK/IRK 只活在 RAM：**每次重启设备重新生成身份/密钥，而手机还记着上一次的** ——
6	两边对不上，链路能建但不加密/服务发现走不动，Android 超时拆链（现场 `hciReason: 22`）。
7	
8	做法：**只搬字节**，复用 zblue 自己的序列化尺寸 `BT_KEYS_STORAGE_LEN`
9	（保存方向 `keys->storage_start`；加载方向 `bt_keys_get_addr()` + `memcpy(keys->storage_start, …)`）。
10	
11	落点：
12	  · `bt_keys_store()` 尾部          → 顺带存一条
13	  · `bt_keys_find()` / `bt_keys_foreach_type()` 开头 → 惰性恢复一次（`myvendor_keys_loaded` 保护）
14	
15	文件：`"BTKY" | ver u8 | 0 u8 | n u16 | 记录 × n`，记录 =
16	        `dev_id u8 | id u16 | addr_type u8 | addr[6] | storage[BT_KEYS_STORAGE_LEN]`
17	
18	自检：`git -C external/zblue/zblue diff -- subsys/bluetooth/host/keys.c` 应只有本补丁的插入。
19	"""
20	
21	import sys
22	from pathlib import Path
23	
24	MARK = "MYVENDOR BUILD: patch_keys_kv.py"
25	
26	
27	def safe_path(raw: str) -> Path:
28	    """构建期调用，仍按不可信输入处理：拒绝 '..'，只接受文件路径。"""
29	    if ".." in Path(raw).parts:
30	        raise SystemExit("refusing path containing '..': %s" % raw)
31	    p = Path(raw).resolve()
32	    if p.is_dir():
33	        raise SystemExit("expected a file path, got a directory: %s" % p)
34	    return p
35	
36	
37	HEADER = r'''
38	/* ---- my_vendor: 配对密钥落盘（vela_override/zblue/patch_keys_kv.py）----
39	 * settings 关着 ⇒ bt_keys_store() 是空动作；这里把同一份 BT_KEYS_STORAGE_LEN
40	 * 字节存到 KV、开机再塞回 key_pool。只搬字节，不猜结构体。 */
41	#include <fcntl.h>
42	#include <stdio.h>
43	#include <string.h>
44	#include <unistd.h>
45	
46	#define MYVENDOR_KEYS_KV_PATH  "/mnt/kv/bt_keys.bin"
47	#define MYVENDOR_KEYS_KV_MAGIC 0x594b5442u   /* "BTKY" */
48	#define MYVENDOR_KEYS_KV_MAX   8u
49	
50	struct myvendor_keys_rec_s
51	{
52		uint8_t  dev_id;
53		uint16_t id;
54		uint8_t  addr_type;
55		uint8_t  addr[6];
56		uint8_t  storage[BT_KEYS_STORAGE_LEN];
57	};
58	
59	static bool myvendor_keys_loaded;
60	
61	static unsigned myvendor_keys_read(struct myvendor_keys_rec_s *out, unsigned max)
62	{
63		uint8_t  hdr[8];
64		uint32_t magic;
65		uint16_t n;
66		int      fd;
67	
68		fd = open(MYVENDOR_KEYS_KV_PATH, O_RDONLY);
69		if (fd < 0) {
70			return 0;
71		}
72		if (read(fd, hdr, sizeof(hdr)) != (ssize_t)sizeof(hdr)) {
73			close(fd);
74			return 0;
75		}
76		memcpy(&magic, hdr, 4);
77		memcpy(&n, hdr + 6, 2);
78		if (magic != MYVENDOR_KEYS_KV_MAGIC || n > max) {
79			close(fd);
80			LOG_WRN("bt_keys kv: bad header");
81			return 0;
82		}
83		if (read(fd, out, (size_t)n * sizeof(out[0])) != (ssize_t)(n * sizeof(out[0]))) {
84			close(fd);
85			return 0;
86		}
87		close(fd);
88		return n;
89	}
90	
91	static void myvendor_keys_write(const struct myvendor_keys_rec_s *rec, unsigned n)
92	{
93		uint8_t  hdr[8];
94		uint32_t magic = MYVENDOR_KEYS_KV_MAGIC;
95		uint16_t nn = (uint16_t)n;
96		int      fd;
97	
98		fd = open(MYVENDOR_KEYS_KV_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
99		if (fd < 0) {
100			LOG_ERR("bt_keys kv: open for write failed");
101			return;
102		}
103		memcpy(hdr, &magic, 4);
104		hdr[4] = 1;
105		hdr[5] = 0;
106		memcpy(hdr + 6, &nn, 2);
107		(void)write(fd, hdr, sizeof(hdr));
108		(void)write(fd, rec, (size_t)n * sizeof(rec[0]));
109		close(fd);
110	}
111	
112	/* 存一条（按 dev_id/id/addr 覆盖或追加；满了丢最旧）。 */
113	static void myvendor_keys_kv_save(uint8_t dev_id, uint16_t id,
114					  const uint8_t *addr, uint8_t addr_type,
115					  const uint8_t *storage)
116	{
117		struct myvendor_keys_rec_s rec[MYVENDOR_KEYS_KV_MAX];
118		unsigned n = myvendor_keys_read(rec, MYVENDOR_KEYS_KV_MAX);
119		unsigned i;
120		bool     found = false;
121	
122		for (i = 0; i < n; i++) {
123			if (rec[i].dev_id == dev_id && rec[i].id == id &&
124			    rec[i].addr_type == addr_type &&
125			    memcmp(rec[i].addr, addr, 6) == 0) {
126				found = true;
127				break;
128			}
129		}
130		if (!found) {
131			if (n >= MYVENDOR_KEYS_KV_MAX) {
132				memmove(&rec[0], &rec[1], (n - 1u) * sizeof(rec[0]));
133				n--;
134			}
135			i = n++;
136		}
137		rec[i].dev_id    = dev_id;
138		rec[i].id        = id;
139		rec[i].addr_type = addr_type;
140		memcpy(rec[i].addr, addr, 6);
141		memcpy(rec[i].storage, storage, BT_KEYS_STORAGE_LEN);
142		myvendor_keys_write(rec, n);
143		LOG_WRN("bt_keys kv: saved %u record(s)", n);
144	}
145	
146	/* 开机惰性恢复。 */
147	static void myvendor_keys_kv_load_once(void)
148	{
149		struct myvendor_keys_rec_s rec[MYVENDOR_KEYS_KV_MAX];
150		unsigned n;
151		unsigned i;
152	
153		if (myvendor_keys_loaded) {
154			return;
155		}
156		myvendor_keys_loaded = true;
157	
158		n = myvendor_keys_read(rec, MYVENDOR_KEYS_KV_MAX);
159		if (n == 0) {
160			return;
161		}
162	
163		for (i = 0; i < n; i++) {
164			struct bt_dev *hdev = bt_dev_get(rec[i].dev_id);
165			bt_addr_le_t   addr;
166			struct bt_keys *keys;
167	
168			if (hdev == NULL) {
169				continue;
170			}
171			addr.type = rec[i].addr_type;
172			memcpy(addr.a.val, rec[i].addr, 6);
173			keys = bt_keys_get_addr(hdev, rec[i].id, &addr);
174			if (keys == NULL) {
175				LOG_ERR("bt_keys kv: no slot for %s", bt_addr_le_str(&addr));
176				continue;
177			}
178			memcpy(keys->storage_start, rec[i].storage, BT_KEYS_STORAGE_LEN);
179		}
180		LOG_WRN("bt_keys kv: restored %u record(s)", n);
181	}
182	'''
183	
184	LOAD_CALL = "\tif (!myvendor_keys_loaded) {\n\t\tmyvendor_keys_kv_load_once();\n\t}\n"
185	
186	SAVE_CALL = ("\tmyvendor_keys_kv_save_pool();   "
187	             "/* my_vendor: settings 关着，这里自己落盘 */\n")
188	
189	# 保存钩子的落点：**不要用 bt_keys_store()** —— 它属于 settings 的提交链
190	# （keys_commit → settings_save），CONFIG_SETTINGS 关着时永不执行（2026-09-20 实测：
191	# 配对成功、bonded=1，但 /mnt/kv 里根本没有 bt_keys.bin）。
192	# 改成这两个"总会跑"的点：
193	#   bt_keys_get_addr()     —— SMP 建立/更新某个 peer 密钥时
194	#   bt_keys_update_usage() —— 连接/安全等级变化时
195	# 两处都是整池重写（≤8 条，开销可忽略）。
196	SAVE_HOOKS = (
197	    "struct bt_keys *bt_keys_get_addr(",
198	    "void bt_keys_update_usage(",
199	)
200	
201	# 整池落盘：跳过空槽（未使用的 keys 槽 id==0 且地址全 0）。
202	POOL_SAVE_FN = '''
203	static void myvendor_keys_kv_save_pool(void)
204	{
205		for (unsigned i = 0; i < ARRAY_SIZE(key_pool); i++) {
206			struct bt_keys *k = key_pool[i].keys;
207	
208			for (unsigned j = 0; j < CONFIG_BT_MAX_PAIRED; j++) {
209				bool empty = (k[j].id == 0);
210	
211				if (!empty) {
212					myvendor_keys_kv_save(i, k[j].id, k[j].addr.a.val,
213							      k[j].addr.type, k[j].storage_start);
214				}
215			}
216		}
217	}
218	'''
219	
220	def main() -> int:
221	    if len(sys.argv) < 3:
222	        raise SystemExit("usage: patch_keys_kv.py <keys.c> <out.c>")
223	
224	    src_path = safe_path(sys.argv[1])
225	    dst_path = safe_path(sys.argv[2])
226	    src = src_path.read_text(encoding="utf-8")
227	
228	    if MARK in src:
229	        dst_path.write_text(src, encoding="utf-8")
230	        print("my_vendor: keys.c already patched")
231	        return 0
232	
233	    anchor = "static struct bt_keys_pool key_pool[CONFIG_BT_NUM_CTLRS];"
234	    if anchor not in src:
235	        print("my_vendor: keys.c anchor (key_pool) not found", file=sys.stderr)
236	        return 1
