static bool companion_phone_connected(void)
{
  bool connected;

  pthread_mutex_lock(&g_ctx.lock);

  g_hold_le_adv = hold;
  /* 判定侧读本地镜像：本函数可能在持有 g_ctx.lock 时被调用，这里再去拿状态锁
