bool myvendor_pair_phone_addr(bt_address_t *out, uint8_t *out_type)
{
  char      line[96];
  char      addr[32];
  unsigned  type = 1;
  FILE     *f = fopen(PAIR_PHONE_TSV, "r");

  if (f == NULL)
    {
      return false;
    }

  if (fgets(line, sizeof(line), f) == NULL)
    {
      fclose(f);
      return false;
    }
  fclose(f);

  if (sscanf(line, "%31s %u", addr, &type) != 2)
    {
      return false;
    }

  /* 归一化（去冒号/空格、统一大写），再 12 个十六进制字符 = 6 字节地址。 */
  {
    char     norm[32];
    unsigned n = 0;
    size_t   i;

    for (i = 0; addr[i] != '\0' && n + 1u < sizeof(norm); i++)
      {
        const char c = addr[i];

        if (c == ':' || c == ' ' || c == '\t' || c == ',')
          {
            continue;
          }
        norm[n++] = (c >= 'a' && c <= 'f') ? (char)(c - 'a' + 'A') : c;
      }
    norm[n] = '\0';

    if (n < 12u)
      {
        return false;
      }

    for (i = 0; i < 6u; i++)
      {
        unsigned hi = 0;
        unsigned lo = 0;
        char     c1 = norm[i * 2u];
        char     c2 = norm[i * 2u + 1u];

        hi = (c1 >= '0' && c1 <= '9') ? (unsigned)(c1 - '0') : (unsigned)(c1 - 'A' + 10);
        lo = (c2 >= '0' && c2 <= '9') ? (unsigned)(c2 - '0') : (unsigned)(c2 - 'A' + 10);
        if (hi > 15u || lo > 15u)
          {
            return false;
          }
        out->addr[i] = (uint8_t)((hi << 4) | lo);
      }
  }

  if (out_type != NULL)
    {
      *out_type = (uint8_t)(type & 0xffu);
    }
  return true;
}

