int myvendor_devctl_pair_phone(char *addr, size_t len)
{
  /* 读设备侧记录（/mnt/kv/bt_phone.tsv，一行 `ADDR<TAB>TYPE`）：1 = 已配对。 */
  FILE *f = fopen("/mnt/kv/bt_phone.tsv", "r");
  char line[64];

  if (f == NULL) return 0;
  if (fgets(line, sizeof(line), f) == NULL) { fclose(f); return 0; }
  fclose(f);

  if (addr != NULL && len > 0u) {
      unsigned n = 0;
      while (line[n] != '\0' && line[n] != '\t' && line[n] != '\n' && n + 1u < len) {
          addr[n] = line[n];
          n++;
      }
      addr[n] = '\0';
  }
  return 1;
}
```
