def feed(self, data: bytes) -> None:
    spool = getattr(self, "spool", None)
    if spool is not None:
        try:
            spool.write(data)
        except OSError:
            pass
    with self._rx_cv:
        self._rx.extend(data)
        extra = len(self._rx) - RX_RING
        if extra > 0:
            del self._rx[:extra]
        self._rx_cv.notify_all()
    self.push(data)

def rx_snapshot(self) -> bytes:
    with self._rx_cv:
