def note(self, text: str) -> None:
    """提示只上屏/推给客户端，**不进环形缓冲**：环形缓冲会被 `rx` 与 attach 的
    `replay` 原样交出去，提示写进去就会出现"回放一次再写一次"的自我放大。"""
    line = f"\r\n*** serial-hub: {text} ***\r\n".encode("utf-8")
