  if (strlen(norm) < 12u)
    {
      printf("pair: phone record bad addr %s\n", s);
      return;
    }
  norm[12] = '\0';

  {
    struct bt_conn *conn = pair_conn_find(norm, &type);

    if (conn != NULL)
      {
        bt_conn_unref(conn);
