/** @brief `ctl sensor bind <kind> <mac> [type]` —— 解析 MAC 文本并投递绑定。 */
static int cmd_sensor_bind(int argc, char **argv)
{
  const char *kind_text;
  const char *mac_text;
  const char *type_text;
  unsigned    kind;
  unsigned    type;
  uint8_t     addr[MYVENDOR_DEVCTL_SENSOR_ADDR_LEN];
  int         rc;

  if (argc < 3 || argv[0] == NULL || argv[1] == NULL || argv[2] == NULL)
    {
      printf("usage: ctl sensor bind <kind 0HR|1CSC|2CPS> <mac> [addr_type 0pub|1rnd]\n");
      return -EINVAL;
    }

  kind_text = argv[1];
  mac_text  = argv[2];
  type_text = argc >= 4 ? argv[3] : NULL;

  kind = (unsigned)strtoul(kind_text, NULL, 10);
  if (kind > MYVENDOR_DEVCTL_SENSOR_KIND_CPS)
    {
      printf("ctl sensor bind: kind must be 0/1/2 (got %s)\n", kind_text);
      return -EINVAL;
    }

  memset(addr, 0, sizeof(addr));
  if (!sensor_mac_parse(mac_text, addr))
    {
      printf("ctl sensor bind: bad mac '%s' (want AA:BB:CC:DD:EE:FF)\n", mac_text);
      return -EINVAL;
    }

  if (type_text != NULL)
    {
      type = (unsigned)strtoul(type_text, NULL, 10);
      if (type > 1u)
        {
          printf("ctl sensor bind: addr_type must be 0(public)/1(random)\n");
          return -EINVAL;
        }
    }
  else
    {
      /* 省掉 type 时按地址位模式猜：静态随机地址最高两位是 11（0xC0…）。 */
      type = (addr[0] & 0xc0u) == 0xc0u ? 1u : 0u;
    }

  rc = myvendor_devctl_sensor_connect_addr(addr, (uint8_t)type, (uint8_t)kind, NULL);
  if (rc != 0)
    {
      printf("ctl sensor bind: failed rc=%d\n", rc);
      return rc;
    }

  printf("ctl sensor bind: %s kind=%u type=%u -> companion\n", mac_text, kind, type);
  return 0;
}
```
