{"file_path": "/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/services/myvendor_gnss.c", "new_string": "  /* **按 u-blox `UBX-MGA-INI-TIME_UTC` 表组帧**（2026-09-20 修）：
   *
   *   offset 0  U1  type   = 0x10
   *   offset 1  U4  ref    = UTC 秒（参考时间）
   *   offset 5  I1  leapSecs = 18
   *   offset 6  U1  valid  = 0x03（日期有效 | 闰秒有效）
   *   offset 7  U4  tAcc   = 精度估计，**纳秒**
   *
   * 以前这里（以及 App 写进星历文件的同一帧）用的是**自定义布局**：把年月日时分秒
   * 塞在 offset 4..10、tAcc 以秒放在 offset 16。模组按自己的表去解析 ⇒ `ref` 读成
   * 一串垃圾秒数 ⇒ **模组的 RTC 被写坏**（现场：它开始报 `utc=2929178425`＝公元 2062，
   * 我们又把系统钟跟着设成那个值，看门狗 dump 里的 `mod time` 刷屏也来自这里）。
   * 用户口径"灌之前先保证自己的时间是对的"——发出去的东西必须先是对的。 */
  memset(pl, 0, sizeof(pl));
  pl[0] = 0x10;
  pl[1] = (uint8_t)(utc & 0xffu);
  pl[2] = (uint8_t)((utc >> 8) & 0xffu);
  pl[3] = (uint8_t)((utc >> 16) & 0xffu);
  pl[4] = (uint8_t)((utc >> 24) & 0xffu);
  pl[5] = 18;                 /* leapSecs */
  pl[6] = 0x03;               /* valid：日期 + 闰秒 */
  {
    /* tAcc：5 s → 纳秒（U4）。 */
    uint32_t ns = (uint32_t)tacc_s * 1000000000u;

    pl[7]  = (uint8_t)(ns & 0xffu);
    pl[8]  = (uint8_t)((ns >> 8) & 0xffu);
    pl[9]  = (uint8_t)((ns >> 16) & 0xffu);
    pl[10] = (uint8_t)((ns >> 24) & 0xffu);
  }
  gnss_drain(fd);
  (void)gnss_ubx_send(fd, 0x13, 0x40, pl, sizeof(pl));
  (void)gnss_ubx_read_frame(fd, &cls, &id, &rlen, GNSS_EPH_ACK_MS);

  syslog(LOG_WARNING, "gnss: time aid utc=%lu src=%s tacc=%us\n",
         (unsigned long)utc, src, tacc_s);
}
