/** @brief calloc 风格 bump 分配。 */
void *mtp_psram_calloc(size_t n, size_t size)
{
  size_t total;
  void *p;

  if (n != 0 && size > (size_t)-1 / n)
    {
      return NULL;
    }

  total = n * size;
  p     = mtp_psram_malloc(total);
  if (p != NULL)
    {
      memset(p, 0, total);
    }

  return p;
}

