/** @brief 自行车/vmap 是否必须推迟 LittleFS I/O。 */
bool myvendor_mtp_lfs_quiesce(void)
{
  bool q;
  bool hold_live = false;

  pthread_mutex_lock(&g_mtp_lock);

  if (g_lfs_hold > 0)
    {
      /* hold 只在"它附近确实有会话/传输"或"还没过保鲜期"时才算数。
       *
       * 否则一个**泄漏的残留 hold 会永久挡死星历注入** —— 现场就是
       * `xfer=0 hold=1 sess=0 plug=0`：只有 hold 命中，而释放路径要么在
       * MTP worker 里（USB 关闭时 worker 不跑），要么在某个提前返回的
       * 分支上被漏掉了。手机刚下发的新星历因此被整段丢弃，
       * 表现就是"手机推了星历，GNSS 却没同步"。
