=== bump 逻辑 ===
/* **空轮回连退避**（2026-09-20 加）：一台绑定过、但此刻不在附近的外设，不该让射频
 * 一直"2 s 广播 → 停广播 → 1 s 扫描"空转 —— 本控制器广播与扫描不能同时开，每一轮
 * 扫描都要先把手机广播停掉（用户原话："注意好节奏"）。做法：一轮扫描没能连上任何
 * 东西，就把**下一轮之前的广播窗口**按 2/4/8/16 s 拉长（上限
 * `SENSOR_RECONNECT_IDLE_MAX_MS`）；连上一次、或用户重扫/重绑/恢复流程，清零。
 * 扫描窗口本身不动（还是 1 s），所以"外设回来了"最坏只等一个退避周期。 */
static uint32_t s_reconnect_idle_cycles;
#define SENSOR_RECONNECT_IDLE_MAX_MS  32000u

/** `s_reconnect_idle_cycles` 的专用锁（2026-09-20）。
 *
 * 这个计数被三个上下文摸：射频相位机（companion 线程）、GATTC 连接成功回调
 * （协议栈线程）、用户绑定/恢复流程。**不复用 `g_lock`**：那几处有的已持锁、
 * 有的没持（`g_lock` 是非递归的），复用会引入死锁；独立一把小锁最稳。 */
static pthread_mutex_t g_idle_cycles_lock = PTHREAD_MUTEX_INITIALIZER;

/** @brief 空轮计数 +1（不满 6 不再涨），返回涨完后的值。 */
static uint32_t reconnect_idle_cycles_bump(void)
{
  uint32_t v;

  pthread_mutex_lock(&g_idle_cycles_lock);
  if (s_reconnect_idle_cycles < 6u)
    {
      s_reconnect_idle_cycles++;
    }
  v = s_reconnect_idle_cycles;
  pthread_mutex_unlock(&g_idle_cycles_lock);
  return v;
}

/** @brief 清零空轮计数（连上了 / 用户重扫重绑 / 恢复流程）。 */
static void reconnect_idle_cycles_reset(void)
{
  pthread_mutex_lock(&g_idle_cycles_lock);
  s_reconnect_idle_cycles = 0u;
  pthread_mutex_unlock(&g_idle_cycles_lock);
}
