bool myvendor_mtp_lfs_quiesce(void)
{
  bool q;
  bool hold_live = false;

  pthread_mutex_lock(&g_mtp_lock);

  if (g_lfs_hold > 0)
    {
      /* hold 只在"它附近确实有会话/传输"或"还没过保鲜期"时才算数。
       *
       * 否则一个**泄漏的残留 hold 会永久挡死星历注入** —— 现场就是
       * `xfer=0 hold=1 sess=0 plug=0`：只有 hold 命中，而释放路径要么在
       * MTP worker 里（USB 关闭时 worker 不跑），要么在某个提前返回的
       * 分支上被漏掉了。手机刚下发的新星历因此被整段丢弃，
       * 表现就是"手机推了星历，GNSS 却没同步"。
       *
       * 保留保鲜期的理由：hold 的本意是"UI/App 马上要用 LFS，别人让一让"，
       * 这种预约天然是短时的（秒级）；超过保鲜期还没归还，就是泄漏而不是预约。 */
      hold_live = g_session || g_transfer_active ||
                  myvendor_mono_elapsed_ms(myvendor_mono_ms(),
                                           g_lfs_hold_ms) <
                      MYVENDOR_MTP_LFS_HOLD_MAX_MS;

      if (!hold_live)
        {
          /* 泄漏的残留 hold：**在源头回收，而不只是"这次忽略它"**。
           *
           * 只忽略的话这个计数会永远挂着：下一个取用方从 1 起算（本该从 0），
           * 而且每个消费者都得各自等过这 30 s —— 现场就是倒库/注入被白挡
           * 二十多秒（还按字节率刷日志）。这里直接清零，让它回到"没人占"；
           * 晚到的 release 由下溢保护挡住，不会变成负数。
           *
           * 这是缺陷信号、不是常态，所以最多打三次。 */
          char tr[96];
          static uint32_t stale_n;

          g_lfs_hold = 0;
          g_lfs_hold_ms = 0;

          if (stale_n < 3u)
            {
              stale_n++;
              mtp_hold_trace_fmt(tr, sizeof(tr));
              syslog(LOG_WARNING,
                     "mtp: leaked lfs_hold reclaimed (age>=%u ms, sess=0 xfer=0 "
                     "plug=0, last takes: %s) — LFS unblocked\n",
                     (unsigned)MYVENDOR_MTP_LFS_HOLD_MAX_MS, tr);
            }
        }
    }

  q = g_transfer_active || hold_live
      || g_plug >= MYVENDOR_MTP_PLUG_ENUM || g_session;

  pthread_mutex_unlock(&g_mtp_lock);
  return q;
}
